// ItemActions is an item page's action bar composed by name (2026-11-10
// design §9.6): the bar (actionBar) with the actions asked for, in the
// order asked, each rendered only when the item takes it (itemAction) --
// Refresh always (as "Refresh & Scan" when the item's folder is on disk,
// d.HasFolder, else "Refresh"); Search always, worded by the kind (searchLabel);
// Interactive for a kind with an interactive search of its own
// (InteractiveSearchable), posting to the item's search/interactive route
// and opening the kind's modal region, #<kind>-modal, as data-action
// "<kind>-interactive-search"; Rename (the dry run and the apply) only for
// an item whose folder is on disk; Edit only for a kind the Edit dialog knows
// (Editable); Images only for a kind with image sets (ImageSettable);
// Delete only for a deletable kind with no delete pending. A page's region
// for the modal is its own to render. The slots are joined with one space
// each, as the bar's buttons always rendered, an empty slot's included.
//
// Since 2026-11-28 (the Liquid Glass redesign, after the Music and TV
// apps) the bar is one line that never wraps: the item's one primary action
// as a labelled prominent capsule -- Search while the item lacks its file
// or is below its cutoff, Refresh otherwise (primaryAction) -- the
// interactive search as a clear-glass circle, and every other action in a
// "…" popover of the same buttons and forms, Delete last.
func ItemActions(d Detail, actions []Action) templ.Component {
	primary := primaryAction(d, actions)
	var face, circles, more []templ.Component
	for _, a := range actions {
		c := itemAction(d, a)
		switch {
		case a == primary:
			face = append(face, c)
		case a == ActionInteractive:
			circles = append(circles, c)
		default:
			more = append(more, c)
		}
	}
	return templ.ComponentFunc(func(ctx context.Context, w io.Writer) error {
		return actionBar().Render(templ.WithChildren(ctx, actionRow(d.Item.Ref.Name, primary == ActionSearch, joined(face), joined(append(circles, monitorBookmark(d.Item))), joined(more), len(more) > 0)), w)
	})
}

// actionSet lays a page's own bar out as ItemActions does (album, episode,
// issue): search the primary action while the item is wanted, else
// refresh; the interactive search a circle; the other of the two and the
// rest in the "…" popover.
func actionSet(name string, wanted bool, monitor, refresh, search, interactive templ.Component, rest ...templ.Component) templ.Component {
	face, other := refresh, search
	if wanted {
		face, other = search, refresh
	}
	more := append([]templ.Component{other}, rest...)
	return templ.ComponentFunc(func(ctx context.Context, w io.Writer) error {
		return actionBar().Render(templ.WithChildren(ctx, actionRow(name, wanted, face, joined([]templ.Component{interactive, monitor}), joined(more), true)), w)
	})
}

// primaryAction is the bar's prominent action: Search while the item is
// missing its file or below its cutoff, else Refresh; whichever of the two
// the page's bar has.
func primaryAction(d Detail, actions []Action) Action {
	want := ActionRefresh
	switch projection.LibraryStatus(d.Item) {
	case "missing", "cutoff-unmet":
		want = ActionSearch
	}
	if slices.Contains(actions, want) {
		return want
	}
	for _, a := range []Action{ActionRefresh, ActionSearch} {
		if slices.Contains(actions, a) {
			return a
		}
	}
	return ""
}

